from pathlib import Path
import json, math
from shapely.geometry import shape
from shapely.ops import unary_union
root=Path('.')
ufs=[('AM','Amazonas'),('PA','Pará'),('AP','Amapá'),('RR','Roraima')]
geoms={uf:unary_union([shape(f['geometry']) for f in json.loads((root/'municipios'/f'municipios_{uf}.geojson').read_text(encoding='utf-8'))['features']]).simplify(.035,preserve_topology=True) for uf,_ in ufs}
def svgpaths(g,project):
 polys=list(g.geoms) if g.geom_type=='MultiPolygon' else [g]
 return ' '.join('M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in map(project,p.exterior.coords))+' Z' for p in polys)
def project(c):
 return ((c[0]+75)*20+20, (7-c[1])*20+20)
paths=''
for uf,_ in ufs:
 paths+=f'<path class="region" d="{svgpaths(geoms[uf],project)}"/>'
lines=json.loads(Path('infovias.geojson').read_text(encoding='utf-8'))['features']
for f in lines:
 g=f['geometry']; coords=[g['coordinates']] if g['type']=='LineString' else g['coordinates']
 for line in coords:
  paths+='<path class="route" d="M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in map(project,line))+'"/>'
for uf,c in [('AM',(-64,-4)),('PA',(-53,-5)),('RR',(-61,2)),('AP',(-51.8,1.8))]:
 x,y=project(c);paths+=f'<text x="{x}" y="{y}" class="region-label">{uf}</text>'
svg=f'<svg viewBox="0 0 630 460" role="img" aria-label="Mapa dos estados de Amazonas, Pará, Amapá e Roraima com os traçados das infovias da base local"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#263b4b" stroke-width=".5"/></pattern></defs><rect width="630" height="460" fill="url(#grid)"/>{paths}</svg>'
cards=''
for uf,name in ufs:
 g=geoms[uf];a,b,c,d=g.bounds
 def miniature(pt):return ((pt[0]-a)/max(c-a,d-b)*85+5,(d-pt[1])/max(c-a,d-b)*85+5)
 mini=f'<svg viewBox="0 0 100 100" aria-hidden="true"><path d="{svgpaths(g,miniature)}"/></svg>'
 cards+=f'<a class="state-card" href="mapa.html?uf={uf}" aria-label="Explorar {name}">{mini}<span class="state-code">{uf}</span><h3>{name}</h3><p><span data-count="{uf}">—</span> localidades consolidadas</p><span class="state-action">Explorar território <span aria-hidden="true">↗</span></span></a>'
html='''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Explore infovias e localidades de AM, PA, AP e RR. Consulte territórios, áreas de influência e dados demográficos."><title>Geoportal Evereste | Inteligência territorial na Amazônia</title>
<style>
:root{color-scheme:dark;--bg:#0b131d;--panel:#121f2c;--line:#283846;--muted:#a9b8c8;--text:#f2f6fa;--accent:#70d6e7}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:95px}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif;line-height:1.65}a{color:inherit;text-decoration:none}a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}a:hover{color:var(--accent)}.wrap{max-width:1240px;margin:auto;padding:0 36px}.skip{position:absolute;left:20px;top:-100px;background:#fff;color:#111;padding:12px;z-index:10}.skip:focus{top:10px}header{border-bottom:1px solid var(--line);background:var(--bg)}.nav{min-height:88px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:12px;font-size:19px;font-weight:650}.brand img{width:48px;height:48px;object-fit:contain}nav{display:flex;gap:26px;align-items:center;font-size:13px;color:var(--muted)}.nav-cta{border:1px solid #537486;border-radius:6px;padding:9px 16px;color:var(--text)}.hero{display:grid;grid-template-columns:1fr 1.05fr;gap:52px;align-items:center;padding:70px 0 50px}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700;color:var(--accent);text-transform:uppercase;margin:0 0 20px}h1{font-size:clamp(34px,3.8vw,49px);line-height:1.14;letter-spacing:-1.8px;font-weight:650;margin:0 0 24px}h1 span{color:var(--accent)}.intro{font-size:16px;color:var(--muted);max-width:490px}.actions{display:flex;gap:22px;align-items:center;flex-wrap:wrap;margin-top:30px}.button{background:var(--accent);color:#09222d;border-radius:6px;padding:13px 22px;font-weight:700;font-size:14px}.button:hover{background:#a2e5f0;color:#09222d}.secondary{font-size:13px;border-bottom:1px solid #526879;padding-bottom:3px}.map-card{margin:0;border:1px solid var(--line);border-radius:12px;background:#101e2b;overflow:hidden}.map-head{padding:15px 20px;display:flex;justify-content:space-between;font-size:11px;letter-spacing:1px;color:var(--muted);border-bottom:1px solid var(--line)}.map-card svg{display:block;width:100%;height:auto}.region{fill:#1b3545;stroke:#64808f;stroke-width:1}.route{fill:none;stroke:#73deeb;stroke-width:1.2;opacity:.9}.region-label{fill:#e4f4f7;font-size:14px;font-weight:600;text-anchor:middle;paint-order:stroke;stroke:#183241;stroke-width:4px}.map-card figcaption{padding:15px 20px;color:var(--muted);font-size:11px;border-top:1px solid var(--line)}.legend-line{display:inline-block;width:24px;height:2px;background:var(--accent);vertical-align:middle;margin-right:8px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:24px 0;margin-bottom:65px}.metric{padding:0 24px;border-right:1px solid var(--line)}.metric:first-child{padding-left:0}.metric:last-child{border:0}.metric strong{display:block;font-size:29px;font-weight:600;line-height:1.3}.metric span{font-size:12px;color:var(--muted)}section{scroll-margin-top:30px}.section-heading{display:flex;justify-content:space-between;gap:30px;align-items:end;margin-bottom:25px}.section-heading h2{margin:0;font-size:27px;letter-spacing:-.7px;font-weight:600}.section-heading p{margin:0;color:var(--muted);font-size:13px;max-width:410px}.features,.states{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.features{margin-bottom:70px}.feature{border-top:1px solid #4b6477;padding:22px 16px 0 0}.step{font-size:12px;color:var(--accent)}h3{font-size:17px;font-weight:600;line-height:1.4;margin:14px 0 10px}.feature p,.state-card p{font-size:13px;color:var(--muted);margin:0}.state-card{position:relative;border:1px solid var(--line);background:var(--panel);border-radius:9px;padding:24px;transition:border-color .2s,background .2s;overflow:hidden}.state-card:hover{border-color:var(--accent);background:#18303c}.state-card svg{position:absolute;width:90px;height:90px;right:15px;top:18px;opacity:.8}.state-card svg path{fill:#284855;stroke:#70b5c6;stroke-width:1}.state-code{font-size:11px;letter-spacing:1px;color:var(--accent)}.state-card h3{margin-top:50px}.state-action{display:flex;justify-content:space-between;font-size:12px;margin-top:26px;color:var(--accent)}.data{display:grid;grid-template-columns:1fr 1.3fr;gap:60px;margin:70px 0;padding:34px;border:1px solid var(--line);border-radius:10px;background:#101c28}.data h2{font-size:26px;line-height:1.25;margin:10px 0 18px}.data p{font-size:13px;color:var(--muted)}details{border-bottom:1px solid var(--line);padding:15px 0}summary{cursor:pointer;font-size:14px;font-weight:600}details p{margin-bottom:0}.catalog-link{display:inline-block;margin-top:15px;border-bottom:1px solid var(--accent);color:var(--accent);font-size:13px}footer{border-top:1px solid var(--line);padding:28px 0 34px;color:var(--muted);font-size:12px}.footer-grid{display:flex;justify-content:space-between;gap:30px}.footer-grid strong{color:var(--text);display:block;font-size:14px}.credits{text-align:right}.notice{font-size:11px;color:var(--muted);margin:-50px 0 60px}
@media(max-width:950px){.hero{gap:28px}.wrap{padding:0 24px}nav{gap:14px}.features,.states{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.nav{flex-wrap:wrap;padding:18px 24px;gap:14px}nav{width:100%;display:grid;grid-template-columns:1fr 1fr;align-items:center;font-size:12px;gap:10px}.nav-cta{text-align:center}.brand{font-size:17px}.hero{grid-template-columns:1fr;padding-top:40px;gap:30px}h1{font-size:37px}.metrics{margin-bottom:40px}.metric{padding:0 12px}.metric strong{font-size:23px}.section-heading{display:block}.section-heading p{margin-top:10px}.features{margin-bottom:45px}.state-card{padding:18px}.data{grid-template-columns:1fr;padding:24px;gap:10px;margin:45px 0}.footer-grid{display:block}.credits{text-align:left;margin-top:18px}.notice{margin-top:-24px}.actions{gap:18px}.secondary{font-size:12px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
</style></head><body><a class="skip" href="#conteudo">Pular para o conteúdo</a>
<header><div class="wrap nav"><a class="brand" href="index.html"><img src="logo_evereste.png" alt="Evereste"><span>Geoportal Evereste</span></a><nav aria-label="Navegação principal"><a href="#visao-geral">Visão geral</a><a href="#territorios">Territórios</a><a href="#dados">Dados e metodologia</a><a class="nav-cta" href="mapa.html">Acessar mapa ↗</a></nav></div></header>
<main id="conteudo" class="wrap"><section class="hero" id="visao-geral"><div><p class="eyebrow">Infovias da Região Norte</p><h1>Inteligência territorial para a <span>conectividade na Amazônia.</span></h1><p class="intro">Explore infovias, consulte localidades e analise áreas de influência no Amazonas, Pará, Amapá e Roraima.</p><div class="actions"><a class="button" href="mapa.html">Explorar mapa ↗</a><a class="secondary" href="#dados">Conhecer dados e metodologia</a></div></div><figure class="map-card"><div class="map-head"><span>ABRANGÊNCIA TERRITORIAL</span><span>AM · PA · AP · RR</span></div>__MAP__<figcaption><span class="legend-line"></span>Traçados das infovias · Base local<br>Limites agregados dos municípios. Geometrias simplificadas para apresentação.</figcaption></figure></section>
<div class="metrics" aria-label="Abrangência da base"><div class="metric"><strong>4</strong><span>estados contemplados</span></div><div class="metric"><strong id="total-localities">—</strong><span>localidades consolidadas</span></div><div class="metric"><strong>Até 50 km</strong><span>raio de análise de proximidade</span></div></div>
<section aria-labelledby="features-title"><div class="section-heading"><h2 id="features-title">Do território à análise</h2><p>Ferramentas para explorar a infraestrutura e compreender seu contexto territorial.</p></div><div class="features"><article class="feature"><span class="step">01 / EXPLORAR</span><h3>Explorar territórios</h3><p>Consulte municípios e localidades e visualize as camadas geográficas disponíveis.</p></article><article class="feature"><span class="step">02 / ANALISAR</span><h3>Analisar proximidade</h3><p>Identifique localidades próximas às infovias e delimite uma área de influência.</p></article><article class="feature"><span class="step">03 / COMPREENDER</span><h3>Consultar indicadores</h3><p>Examine os dados demográficos com seus critérios de seleção e estimativa.</p></article><article class="feature"><span class="step">04 / DOCUMENTAR</span><h3>Produzir relatórios</h3><p>Exporte resultados com mapa e metodologia, ou baixe as localidades em CSV.</p></article></div></section>
<section id="territorios" aria-labelledby="states-title"><div class="section-heading"><h2 id="states-title">Escolha seu território</h2><p>Abra o ambiente de análise com o estado selecionado.</p></div><div class="states">__STATES__</div></section>
<section id="dados" class="data" aria-labelledby="data-title"><div><p class="eyebrow">Transparência dos dados</p><h2 id="data-title">Contexto para interpretar cada resultado.</h2><p>A proximidade da infraestrutura indica uma potencial área de influência. Não comprova cobertura de sinal, conexão instalada ou atendimento efetivo.</p><a class="catalog-link" href="data-catalog.json" target="_blank" rel="noopener">Consultar catálogo das bases ↗</a></div><div><details open><summary>Como são calculados os indicadores?</summary><p>A análise territorial utiliza os totais registrados para o município. A análise por proximidade soma os setores cujo centroide está dentro do buffer; o resultado é uma estimativa, não uma contagem exata da população na faixa.</p></details><details><summary>Qual é a referência dos dados?</summary><p>A aplicação declara o Censo 2022 como referência demográfica. A origem e as transformações das bases ainda precisam de confirmação documental. O catálogo identifica os arquivos, seus registros de origem e as contagens consolidadas. A consolidação usa nome igual no mesmo município e coordenadas com diferença inferior a 0,0001 grau, preservando as categorias.</p></details><details><summary>Quais são os limites da análise?</summary><p>Os setores disponíveis são um recorte de 50 km. Categorias filtram localidades, não a demografia territorial. Capital corresponde ao município completo, incluindo sua área rural.</p></details></div></section><p id="catalog-status" class="notice" role="status">Consultando as contagens do catálogo de dados…</p></main>
<footer><div class="wrap footer-grid"><div><strong>Geoportal Evereste</strong>Infovias da Região Norte · © 2026</div><div class="credits"><strong>Território Digital · IGeoTecnologia</strong>Desenvolvimento de sistemas e geotecnologias</div></div></footer>
<script>
(async()=>{try{const response=await fetch('data-catalog.json');if(!response.ok)throw new Error('Catálogo indisponível');const catalog=await response.json();let total=0;let rawTotal=0;for(const uf of ['AM','PA','AP','RR']){const entry=catalog.datasets.find(d=>d.path===`localidades_por_uf/localidades_${uf}.geojson`);if(!entry||!Number.isInteger(entry.consolidatedFeatures))throw new Error('Catálogo incompleto');document.querySelector(`[data-count="${uf}"]`).textContent=entry.consolidatedFeatures.toLocaleString('pt-BR');total+=entry.consolidatedFeatures;rawTotal+=entry.features}document.getElementById('total-localities').textContent=total.toLocaleString('pt-BR');document.getElementById('catalog-status').textContent=`${total.toLocaleString('pt-BR')} localidades consolidadas a partir de ${rawTotal.toLocaleString('pt-BR')} registros de origem. Categorias preservadas; regra detalhada na metodologia.`}catch(error){document.getElementById('catalog-status').textContent='Contagens indisponíveis no momento. O mapa permanece acessível.'}})();
</script></body></html>'''
Path('index.html').write_text(html.replace('__MAP__',svg).replace('__STATES__',cards),encoding='utf-8')
